const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close −':'Menu +'});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.project').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));
const stars=[['demera','Demera Activation','Live & culture','p9-0.jpeg','A cultural gathering brought to life through Shinning Star’s Demera activation.'],['safaricom','Safaricom Football','Sports & tournaments','p12-0.jpeg','A Safaricom football tournament in western Ethiopia, connecting participants and communities through sport.'],['guaro','Guaro Fest','Brand experience','p14-2.jpeg','An outdoor festival experience bringing brands and communities into a shared space.'],['harar','Harar Bazar','Live entertainment','p17-0.jpeg','A vibrant bazaar and live entertainment experience from the company portfolio.'],['construction','Construction Exhibition','Exhibitions','p16-0.jpeg','An exhibition connecting people, equipment, and the construction industry.'],['meat-combo','Meat Combo','Brand activation','p8-1.jpeg','An outdoor Bedele brand activation, featured in the company profile as Meat Combo.']];
document.querySelectorAll('[data-star]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-star]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});const p=stars[Number(b.dataset.star)];const im=document.querySelector('#star-photo');im.src='assets/'+p[3];im.alt=p[1];document.querySelector('#star-type').textContent=p[2];document.querySelector('#star-title').textContent=p[1];document.querySelector('#star-description').textContent=p[4];document.querySelector('#star-link').href='project-'+p[0]+'.html'}));
const cursor=document.querySelector('#cursor');if(matchMedia('(pointer:fine)').matches){document.addEventListener('pointermove',e=>{cursor.classList.add('visible');cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';cursor.style.fontSize=e.target.closest('a,button,summary')?'40px':'28px'});document.addEventListener('pointerleave',()=>cursor.classList.remove('visible'))}
document.querySelector('#brief-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const text=['SHINNING STAR — CREATIVE BRIEF','',...Array.from(d,([k,v])=>k.toUpperCase()+': '+(v||'To be confirmed')),'','Saved locally. This brief has not been sent.'].join('\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='shinning-star-creative-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Your brief is ready. Your browser will save it to your device.'});
